J.hunt.starfall={runs=Fl,perWave=El.perWave and(El.perWave+(Bl-El.perWave)*Gl)or Bl,hpK=Cl and(El.hpK and(El.hpK+(Cl-El.hpK)*Gl)or Cl)or El.hpK,at=os.time()}
