for ln,mn in pairs(type(kn)==Byc[1495]and kn or{})do
if type(mn)==Byc[1495]and mn._t then
jn.rolls[tostring(mn._t)]=(jn.rolls[tostring(mn._t)]or 0)+(tonumber(mn._d)or 0)
end
