function eb.charmScore(sn,tn)
local un=(tn and tonumber(tn.p))or 0.5
local vn,wn,xn=sn.rolls.unit_damage or 0,sn.rolls.reward_mul or 0,0
for yn,zn in pairs(sn.rolls)do
if yn~=Byc[1711]and yn~=Byc[1712]then
xn=xn+zn
end
end
if un>=0.92 then
return wn*3+vn+xn*0.5
end
return vn*3+wn+xn*0.5
end
function eb.charmWords(An)
local Bn={}
for Cn,Dn in pairs(An.rolls)do
table.insert(Bn,string.format(Byc[1713],Cn==Byc[1711]and Byc[1629]or(Cn==Byc[1712]and Byc[1714]or Cn),math.floor(Dn*100+0.5)))
end
table.sort(Bn)
return string.format(Byc[1715],An.tier,#Bn>0 and table.concat(Bn,Byc[1591])or Byc[1716])
end
function eb.charmDmg(En)
if type(En)~=Byc[1495]or not(eb.is(En.id)or En.portal_group==Byc[1717]or tostring(En.id):find(Byc[1718],1,true))then
return 0
end
local Fn,Gn=eb.charmOn(),0
for Hn,In in ipairs(eb.charms())do
local Jn=In.rolls.unit_damage or 0
if Fn and In.uuid==Fn then
return Jn
end
if I.smartCharm and Jn>Gn then
Gn=Jn
end
end
return Fn and 0 or Gn
end
function eb.charmWant(Kn)
if not I.smartCharm or not eb.charmApplies(Kn)then
return nil
end
J.charm=type(J.charm)==Byc[1495]and J.charm or{}
if os.time()-(tonumber(J.charm.failAt)or 0)<1800 then
return nil
end
local Ln,Mn
for Nn,On in ipairs(eb.charms())do
local Pn=eb.charmScore(On,Kn)
if not Mn or Pn>Mn then
Ln,Mn=On,Pn
end
end
if not Ln then
return nil
end
local Qn=eb.charmOn()or(j.where==Byc[1563]and J.charm.uuid)or nil
if Qn==Ln.uuid then
return nil
end
return Ln,Qn
end
function eb.charmTick(Rn)
local Sn,Tn=eb.charmWant(Rn)
if not Sn then
return
end
Tn=eb.charmOn()
if Tn then
j.request(Byc[1719],Byc[1720],Tn)
task.wait(1)
end
j.request(Byc[1719],Byc[1721],Sn.uuid)
local Un=M.now()
while M.now()-Un<4 and eb.charmOn()~=Sn.uuid do
task.wait(0.5)
end
if eb.charmOn()==Sn.uuid then
J.charm.uuid,J.charm.at,J.charm.failAt=Sn.uuid,os.time(),nil
j.saveSoon()
j.log(1,Byc[1722],string.format(Byc[1723],eb.charmWords(Sn),tostring(Rn.label),math.floor((tonumber(Rn.p)or 0)*100+0.5),(tonumber(Rn.p)or 0)>=0.92 and Byc[1714]or Byc[1629]))
else
J.charm.failAt=os.time()
j.saveSoon()
j.log(1,Byc[1722],string.format(Byc[1724],eb.charmWords(Sn)))
end
end
function eb.weatherStrength(Vn)
local Wn=eb.fx(Vn)
local Xn=Wn.dmg/Wn.cd/Wn.hp/Wn.speed*(1+(Wn.range-1)/2)
for Yn,Zn in pairs(Wn.kinds)do
Xn=Xn*(1+Q.rogueShare(Yn)*Zn)
end
if Wn.ice>0 then
local ao=Q.rogueShare(Byc[1674])
Xn=Xn*(ao+(1-ao)/(1-Wn.ice+Wn.ice/W.modFactor(Byc[1725])))
end
if Wn.fly>0 then
Xn=Xn*(1-Wn.fly*0.5)
end
if Wn.noCC then
Xn=Xn*0.95
end
if Wn.shroud then
Xn=Xn*0.9
end
return Xn
end
function eb.cardGems(bo,co)
local eo=0
local fo=eb.pearlsFrom(co+1,50)
for go,ho in pairs(type(bo.effects)==Byc[1495]and bo.effects or{})do
if type(ho)==Byc[1495]then
local io=tonumber(ho.amount)or 0
if ho.type==Byc[1726]then
eo=eo+math.abs(io)*fo*I.pearlValue
elseif ho.type==Byc[1727]then
local jo,ko=pcall(O.rewardValue,ho.reward)
if jo then
eo=eo+(tonumber(ko)or 0)
end
elseif ho.type==Byc[1728]then
eo=eo+io*eb.STARFALL_GEMS
elseif ho.type==Byc[1729]then
eo=eo+io*100
end
end
end
if bo.option_type==Byc[1730]then
eo=eo+eb.HARD_GEMS
end
if bo.weather then
local mo=bo.weather~=eb.weatherNow()
if mo and bo.weather==Byc[1677]then
eo=eo+eb.starfallRemnants(50-(tonumber(co)or 0))*(H.ITEM_VALUE.star_remnant_limited or 25)
end
local no=eb.board()
if mo and no and bo.weather~=Byc[1683]and not no.weathers[bo.weather]then
eo=eo+(1000+5000*I.pearlValue+50*(H.ITEM_VALUE.star_remnant_limited or 25))/eb.WEATHERS
end
end
return eo
end
