end
j.log(1,Byc[1697],string.format(Byc[1793],yq-tq(),(tonumber(((H.prof().capsule_pity_data or{})[eb.STAR]or{}).total_opens)or 0)))
P.pickNote.skins=nil
elseif zq.open>0 then
