if FK<=0 then
return 0
end
local GK=db.whatIf(EK,{xp=math.max(tonumber(EK.xp)or 0,db.xpFor(EK.unit_id,110)),further_modifiers={limit_break={current_limit_break=1}}})
return db.share(EK.unit_id)*(db.score(GK)/FK-1)*100+5
end
