function db.relicWorth(HK,IK)
local JK=IK._unique_item_data and IK._unique_item_data._unique_relic_data
if not JK then
return 0
end
local KK=H.Items[IK.item_id]or{}
local LK,MK=N.types(HK.unit_id)
if KK.main_damage_type and KK.main_damage_type~=Byc[2116]and KK.main_damage_type~=MK then
return 0
end
local NK,OK=0,0
for PK,QK in pairs(JK._core_damage_type_buffs or{})do
if LK[QK.damage_type]then
NK=NK+(tonumber(QK.mul)or 0)+(tonumber(QK.add_upg)or 0)*0.01+(tonumber(QK.pen)or 0)*0.001
OK=OK+(tonumber(QK.crit)or 0)
end
end
NK=NK+OK*0.5
local RK=N.rows(HK.unit_id)
local SK=RK and RK[RK.max]
local TK=(SK and tonumber(SK.cd)or 0)*N.mult(HK,Byc[1630])
for UK,VK in pairs(JK._unique_relic_effects or{})do
local WK=type(VK.params)==Byc[1495]and VK.params or{}
if VK.id==Byc[2117]then
local XK=math.min(1,(tonumber(WK.extra_damage)or 0)*TK/math.max(1,tonumber(WK.time_interval)or 40))
local YK=N.DRONES and N.DRONES[HK.unit_id]
if YK and YK.late and TK>0 then
local ZK=1/TK
XK=XK*ZK/(ZK+(tonumber(YK.max)or 0)*(tonumber(YK.late.dmg)or 0)*(tonumber(YK.hits)or 1)/math.max(0.1,tonumber(YK.late.cd)or 4))
end
NK=NK+XK
elseif VK.id==Byc[2118]then
NK=NK+(tonumber(WK.dmg_buff)or 0)*0.25
elseif VK.id==Byc[2119]then
NK=NK+(tonumber(WK.dmg_buff)or 0)*OK
elseif VK.id==Byc[2120]then
if LK.magic then
NK=0
else
NK=NK+(tonumber(WK.dmg_buff)or 0)*0.3
end
elseif VK.id==Byc[2121]then
if LK.water_damage then
NK=NK+0.05
end
end
end
return NK
end
function db.relicPlan()
local _K=H.session()
