local hL=gL.data and gL.data.rarity
if not N.isFarm(gL.id)and(hL==Byc[1754]or hL==Byc[1755]or hL==Byc[2101]or hL==Byc[2123])then
local iL=db.share(gL.id)
if not J.str.share[gL.id]then
iL=math.min(iL,0.15)
end
local jL={}
for kL,lL in ipairs(bL)do
local mL=db.relicWorth(gL.u,lL)*iL*100
if mL>0.01 then
table.insert(jL,{it=lL,w=mL})
end
end
table.sort(jL,function(nL,oL)
if nL.w~=oL.w then
return nL.w>oL.w
end
return nL.it.uuid<oL.it.uuid
end)
local pL,qL={},{}
for rL,sL in ipairs(jL)do
local tL=qL[sL.it.item_id]or 0
if#pL<6 and tL<((H.Items[sL.it.item_id]or{}).unique_equip and 1 or 2)then
qL[sL.it.item_id]=tL+1
table.insert(pL,sL)
end
end
if gL.u._equipped_relic then
local uL=false
for vL,wL in ipairs(pL)do
if wL.it.uuid==gL.u._equipped_relic then
uL=true
end
end
local xL=not uL and _K.inventory:get_item_by_uuid(gL.u._equipped_relic)
if xL then
table.insert(pL,{it=xL,w=db.relicWorth(gL.u,xL)*iL*100})
end
