local yL,zL={},-1
local AL,BL,CL={},{},{}
local function DL(EL,FL)
if EL> #eL then
if FL>zL then
zL=FL
yL=table.clone(AL)
end
return
end
local GL=eL[EL]
AL[GL.e.uuid]=nil
DL(EL+1,FL)
for HL,IL in ipairs(GL.opts)do
local JL=(H.Items[IL.it.item_id]or{}).unique_equip
if not BL[IL.it.uuid]and not(JL and CL[IL.it.item_id])then
BL[IL.it.uuid]=true
if JL then
CL[IL.it.item_id]=true
end
AL[GL.e.uuid]=IL.it.uuid
DL(EL+1,FL+IL.w+(IL.it.uuid==GL.e.u._equipped_relic and 0.01 or 0))
AL[GL.e.uuid]=nil
BL[IL.it.uuid]=nil
if JL then
CL[IL.it.item_id]=nil
end
end
end
end
DL(1,0)
local KL,LL=0,{}
for ML,NL in ipairs(eL)do
local OL=NL.e.u._equipped_relic and _K.inventory:get_item_by_uuid(NL.e.u._equipped_relic)
local PL=OL and db.relicWorth(NL.e.u,OL)*NL.share*100 or 0
KL=KL+PL
local QL=yL[NL.e.uuid]and _K.inventory:get_item_by_uuid(yL[NL.e.uuid])
