table.insert(LL,string.format(Byc[2124],N.name(NL.e.id),OL and(H.Items[OL.item_id]or{}).name or Byc[1765],PL,QL and(H.Items[QL.item_id]or{}).name or Byc[1765],RL))
end
return yL,zL-KL,LL,eL
end
