function db.run(eO)
local fO=H.session()
local gO=fO and fO.collection:get_unit_by_uuid(eO.uuid)
if not gO then
return
end
if eO.kind==Byc[2135]then
local hO=N.trait(gO)
local iO=hO==Byc[2144]and 1.5 or 1
local jO=math.max(0,db.xpFor(gO.unit_id,db.cap(gO))-(tonumber(gO.xp)or 0))
local kO,lO,mO={},0,0
for nO,oO in ipairs(db.foodHeld())do
local pO=oO.xp*iO
local qO=math.min(oO.n,math.floor((jO-lO)/math.max(1,pO)))
if qO>0 then
kO[oO.id]=qO
lO=lO+qO*pO
mO=mO+qO
end
end
if mO==0 then
J.str.feedNote=eO.name..Byc[2145]
return
end
local rO,sO=tonumber(gO.xp)or 0,db.level(gO)
local tO,uO=j.request(Byc[2135],Byc[2146],eO.uuid,kO)
local vO=M.now()
while M.now()-vO<4 and(tonumber((fO.collection:get_unit_by_uuid(eO.uuid)or gO).xp)or 0)<=rO do
task.wait(0.25)
end
local wO=fO.collection:get_unit_by_uuid(eO.uuid)or gO
local xO=(tonumber(wO.xp)or 0)-rO
if xO>0 then
R.add(string.format(Byc[2147],mO,eO.name),mO,Byc[2148],string.format(Byc[2149],M.fmt(xO),sO,db.level(wO)))
db.note(string.format(Byc[2150],eO.name,mO,M.fmt(xO),sO,db.level(wO),math.abs(xO-lO)>lO*0.1 and string.format(Byc[2151],M.fmt(lO))or Byc[424]))
else
db.note(string.format(Byc[2152],eO.name,tostring(tO and uO or Byc[1778])))
j.backoff(Byc[2135],600)
end
elseif eO.kind==Byc[2140]then
P.fuseInto(eO.uuid,false)
end
end
