function P.evolve(GP,HP)
local IP=H.session()
local JP=IP.collection:get_unit_by_uuid(GP.uuid)
if not JP then
return false,Byc[2197]
end
local KP,LP=0,{}
for MP,NP in pairs(IP.profile_data.collection.owned_units)do
if NP.unit_id==GP.to then
KP=KP+1
LP[MP]=true
end
end
local OP,PP=j.request(Byc[2026],Byc[2198],GP.uuid)
task.wait(2)
local QP=IP.collection:get_unit_by_uuid(GP.uuid)
local RP=0
for SP,TP in pairs(IP.profile_data.collection.owned_units)do
if TP.unit_id==GP.to then
RP=RP+1
if not LP[SP]then
if I.fuseXpUnit==GP.uuid then
I.fuseXpUnit,I.fuseXpId=SP,GP.to
j.saveSoon()
end
if I.fuseUnit==GP.uuid then
I.fuseUnit=SP
j.saveSoon()
end
end
end
end
if RP>KP then
local UP={}
for VP,WP in ipairs(GP.items or{})do
table.insert(UP,string.format(Byc[2199],(H.Items[WP.id]or{}).name or WP.id,WP.amount))
end
for XP,YP in ipairs(GP.eats or{})do
table.insert(UP,string.format(Byc[2200],YP.amount,N.name(YP.id)))
end
local ZP=string.format(Byc[2201],N.name(GP.from),N.name(GP.to),M.fmt(GP.scoreFrom or 0),M.fmt(GP.scoreTo or 0))
R.add(Byc[2202]..ZP,1,Byc[2203],(HP or Byc[2204])..(#UP>0 and(Byc[2205]..table.concat(UP,Byc[1591]))or Byc[424]))
j.log(1,Byc[2206],ZP..Byc[2207]..(HP or Byc[2204])..(#UP>0 and(Byc[2205]..table.concat(UP,Byc[1591]))or Byc[424]))
O._sigAt=nil
pcall(ab.refresh)
return true,N.name(GP.to)..Byc[2208]
end
j.log(1,Byc[2206],Byc[2209]..N.name(GP.from)..Byc[1812]..tostring(PP)..Byc[2210]..tostring(QP and QP.unit_id))
return false,Byc[2211]..tostring(PP)..Byc[1813]
end
