function P.evoEats(_P,aQ)
local bQ=H.session()
local cQ,dQ=pcall(N.score,bQ.collection:get_unit_by_uuid(_P.uuid))
for eQ,fQ in ipairs(_P.eats or{})do
for gQ,hQ in ipairs(ab.copies(fQ.id,fQ.shiny,_P.uuid))do
local iQ=bQ.collection:get_unit_by_uuid(hQ.uuid)or hQ
local jQ,kQ=pcall(N.score,iQ)
if aQ[hQ.uuid]or N.trait(iQ)or(cQ and jQ and kQ>=dQ)then
return string.format(Byc[2212],N.name(fQ.id))
end
end
end
end
