function P.evolveBuyPlan(vQ)
if not(I.autoEvolve and vQ and vQ.pinned and not vQ.ready and vQ.uuid==I.evolveUnit)then
return nil
end
for wQ,xQ in ipairs(vQ.plans or{})do
if xQ.eventShop and(tonumber(xQ.cost)or 0)>0 and xQ.currency and ab.have(xQ.item)<(tonumber(xQ.need)or 1)and(tonumber(H.cur(xQ.currency))or 0)>=xQ.cost then
