function P.evolveBuy(yQ)
local zQ=P.evolveBuyPlan(yQ)
if not zQ or j.where~=Byc[1562]then
return false
end
if j.req.back.evobuy and M.now()<j.req.back.evobuy then
return false
end
local AQ=(H.Items[zQ.item]or{}).name or zQ.item
local BQ=ab.have(zQ.item)
local CQ,DQ=j.request(Byc[2218],Byc[1795],zQ.item,Byc[1512],Byc[1796],Byc[1633])
local EQ=M.now()
while M.now()-EQ<4 and ab.have(zQ.item)<=BQ do
task.wait(0.25)
end
if ab.have(zQ.item)>BQ then
R.add(AQ,zQ.cost,tostring(zQ.currency),Byc[2219]..N.name(yQ.from)..Byc[2220])
if j.notify then
j.notify(Byc[2216],Byc[2042]..AQ..Byc[2160]..N.name(yQ.from),Byc[2044])
end
pcall(ab.refresh)
return true
end
j.log(1,Byc[2045],string.format(Byc[2221],AQ,tostring(CQ and DQ or Byc[1778])))
j.backoff(Byc[2218],900)
return false
end
function P.autoEvolve()
if not I.autoEvolve or I.evolveUnit==Byc[424]then
return
end
local FQ=H.session()
if not(FQ and FQ.collection:get_unit_by_uuid(I.evolveUnit))then
return P.pickDone(Byc[2222],Byc[2216],Byc[2223],Byc[2224])
end
local GQ
for HQ,IQ in ipairs(J.goals or{})do
if IQ.pinned and IQ.uuid==I.evolveUnit then
GQ=IQ
break
end
end
if not GQ then
local JQ=FQ.collection:get_unit_by_uuid(I.evolveUnit)
local KQ=H.Units[JQ.unit_id]
if not(KQ and KQ.evolve and KQ.evolve.evolve_unit)then
P.pickDone(Byc[2222],Byc[2216],N.name(JQ.unit_id)..Byc[2225],Byc[2224])
end
