function P.smartEvolve()
if not I.smartEvolve then
return j.status(Byc[2328],Byc[2329])
end
local rV=H.session()
if not rV then
return
end
local sV={}
for tV,uV in ipairs(J.goals or{})do
table.insert(sV,uV)
end
table.sort(sV,function(vV,wV)
return(vV.gain or 0)>(wV.gain or 0)
end)
local xV={}
for yV,zV in ipairs(N.equipped())do
xV[zV.uuid]=true
end
local AV,BV,CV={},0,{}
for DV,EV in ipairs(sV)do
if EV.pinned then
for FV,GV in ipairs(EV.items or{})do
AV[GV.id]=(AV[GV.id]or 0)+GV.amount
end
end
end
for HV,IV in ipairs(sV)do
local JV,KV
if IV.ready and not IV.pinned and BV<2 and(P.evoBlocked[IV.uuid]or 0)<os.time()then
if IV.hidden and(IV.tierRank or 0)<ab.TIER_RANK.S then
JV=Byc[2330]
end
for LV,MV in ipairs(JV and{}or IV.items or{})do
if ab.have(MV.id)-MV.amount<(AV[MV.id]or 0)then
JV=string.format(Byc[2331],(H.Items[MV.id]or{}).name or MV.id)
break
end
end
JV=JV or P.evoEats(IV,xV)
if not JV then
local NV,OV=P.evolve(IV,Byc[2332]..(#(IV.eats or{})>0 and Byc[2333]or Byc[424]))
if NV then
BV,KV=BV+1,true
table.insert(CV,Byc[2202]..N.name(IV.from)..Byc[2334]..N.name(IV.to))
else
P.evoBlocked[IV.uuid]=os.time()+3600
JV=OV
end
end
if JV then
table.insert(CV,N.name(IV.from)..Byc[1803]..JV)
end
end
if not KV then
for PV,QV in ipairs(IV.items or{})do
AV[QV.id]=(AV[QV.id]or 0)+QV.amount
end
end
end
j.status(Byc[2328],#CV>0 and table.concat(CV,Byc[1692])or Byc[2335])
end
bb.BONUS=1.5
bb.SLOW=1.4
function bb.boost(RV,SV,TV,UV)
if SV<2 or TV>=math.min(I.dangerReach,(UV or 1)*0.9)then
return
end
local VV=TV<math.min(I.safeReach,(UV or 1)*0.75)
local WV=0
for XV,YV in ipairs(RV)do
if not YV.farm and not YV.train and YV.cost>0 then
WV=math.max(WV,YV.gain/YV.cost)
end
end
for ZV,_V in ipairs(RV)do
if _V.train==Byc[2336]or(_V.train==Byc[2337]and VV)then
_V.gain=math.max(_V.gain,WV*_V.cost*1.05)
end
end
end
bb.HOLD_REACH=0.3
bb.ZONE=0.25
function bb.hold(aW,bW,cW)
if bW<2 or aW>=bb.HOLD_REACH+(cW and 0.1 or 0)then
return false
end
return true,string.format(Byc[2338],math.floor(aW*100+0.5))
end
function bb.same(dW,eW)
if#dW~= #eW then
return false
end
local fW={}
for gW,hW in ipairs(dW)do
fW[hW]=true
end
for iW,jW in ipairs(eW)do
if not fW[jW]then
return false
end
end
return true
end
function bb.team()
local kW={}
for lW,mW in ipairs(N.equipped())do
table.insert(kW,mW.uuid)
end
return kW
end
function bb.target()
local nW=H.session()
if not nW then
return nil
end
local oW,pW
local qW=I.autoEvolve and I.evolveUnit~=Byc[424]and I.evolveUnit or nil
for rW,sW in ipairs(J.goals or{})do
local tW,uW=nil,0
for vW,wW in ipairs(sW.plans or{})do
if wW.takedown then
tW=wW
else
uW=uW+1
end
end
local xW=tW and sW.intoTeam and(sW.pinned or not sW.unknown)and(not qW or sW.uuid==qW)and nW.collection:get_unit_by_uuid(sW.uuid)
if xW then
local yW=tonumber(tW.what==Byc[1995]and xW.total_kills or xW.total_takedowns)or 0
if yW<tW.need then
local zW=(uW==0 and 1000 or 0)+(tonumber(sW.tierRank)or 0)*10-rW*0.01
if not oW or zW>pW then
oW,pW={uuid=sW.uuid,id=sW.from,to=sW.to,what=tW.what,have=yW,need=tW.need},zW
end
end
end
end
return oW
end
function bb.realHave(AW)
local BW=H.session()
local CW=BW and BW.collection:get_unit_by_uuid(AW.uuid)
local DW=CW and tonumber(AW.what==Byc[1995]and CW.total_kills or CW.total_takedowns)or 0
return math.max(DW,AW.have+(AW.got or 0))
