function bb.now()
if bb._at and M.now()-bb._at<10 then
return bb._t,bb._base
end
local EW=(J.train.on and J.train.on.base)or bb.team()
local FW=table.clone(EW)
table.sort(FW)
bb._t,bb._base,bb._at=bb.target(),table.concat(FW,Byc[2111]),M.now()
return bb._t,bb._base
end
function bb.valueFor(GW)
if not(I.trainTakedowns and I.goals)then
return 0,1
end
local HW=J.trainSim[GW.key]
if not(HW and HW.ok and os.time()-(HW.at or 0)<6*3600)then
return 0,1
end
local IW,JW=bb.now()
local KW={}
for LW,MW in ipairs(J.savedTeam or{})do
KW[LW]=MW
end
table.sort(KW)
if not(IW and HW.uuid==IW.uuid and(HW.base==JW or HW.base==table.concat(KW,Byc[2111])))or not bb.eligible(GW)then
return 0,1
end
local NW=bb.perRun(GW.key,IW.id)or 0
local OW=math.max(1,IW.need-IW.have)
return I.goalValue*math.min(NW,OW)/OW,HW.slow or 1
end
function bb.scan()
local PW=I.trainTakedowns and I.sim and bb.now()
if not PW then
return
end
local QW=(J.train.on and J.train.on.base)or bb.team()
for RW,SW in ipairs(QW)do
if SW==PW.uuid then
return
end
end
local TW,UW=0,0
for VW,WW in ipairs(O.lastScored or{})do
if TW>=3 or UW>=2 then
break
end
if bb.eligible(WW)then
local XW=J.trainSim[WW.key]
local YW=XW and XW.uuid==PW.uuid and os.time()-(XW.at or 0)<6*3600
local ZW=bb.plan(WW,PW,QW)
if not YW then
UW=UW+1
end
if ZW.ok then
TW=TW+1
end
end
end
local _W=bb.bestInfinite()
if _W then
bb.plan(_W,PW,QW)
end
end
function bb.bestInfinite()
local aX,bX
for cX,dX in ipairs(O.lastScored or{})do
if dX.kind==Byc[1514]and bb.eligible(dX)then
local eX,fX=J.train.real[dX.key],dX.rec or O.rec(dX.key)
local gX=(tonumber(fX.timed)or 0)>0 and fX.sec/fX.timed/60 or 0
local hX=(eX and eX.n>0 and gX>0)and(eX.sum/eX.n)/gX or 0
if hX<=0 then
hX=U.hiveTrainRate(dX.key)or 0
end
if hX>(bX or 0)then
aX,bX=dX,hX
end
end
end
return aX
end
function bb.ratio()
local iX=J.train.cal
if not(iX and(iX.n or 0)>0 and(iX.sim or 0)>0)then
return 1
end
return M.clamp(iX.real/iX.sim,0.05,2)
end
function bb.perRun(jX,kX)
local lX=J.train.real[jX]
if lX and lX.n>0 then
return lX.sum/lX.n,true
end
local mX=U.hiveTrain(jX,kX)
if mX then
return mX,true
end
local nX,oX=0,0
local pX=O.isInf(jX)
for qX,rX in pairs(J.train.real)do
if O.isInf(qX)==pX then
nX,oX=nX+rX.sum,oX+rX.n
end
end
if oX>0 then
return nX/oX,true
end
local sX=J.trainSim[jX]
return sX and sX.tk and sX.tk*bb.ratio()or nil,false
end
function bb.eligible(tX)
if tX.kind==Byc[1647]or tX.kind==Byc[1509]then
return false,Byc[2339]
end
if tX.kind==Byc[1515]then
return false,Byc[2340]
end
if H.Levels[tX.level]and H.Levels[tX.level]._randomequippedmode then
return false,Byc[2341]
end
if(J.train.bad[tX.key]or 0)>os.time()then
return false,Byc[2342]..os.date(Byc[2196],J.train.bad[tX.key])
end
local uX=tX.rec or O.rec(tX.key)
if uX.runs>=3 and uX.wins/uX.runs<0.8 then
return false,Byc[2343]
end
local vX=J.simRes[tX.key]
if vX and vX.trust and not vX.trust.ok then
return false,Byc[2344]
end
return true
end
function bb.plan(wX,xX,yX)
local zX=H.session()
local AX=table.clone(yX)
table.sort(AX)
local BX=table.concat(AX,Byc[2111])
local CX=(tonumber((J.simCal[wX.key]or{}).n)or 0)>0
local DX=CX and 1.3 or 2
local EX=BX..Byc[2345]..xX.uuid..(CX and Byc[2346]or Byc[2347])..Byc[2348]
local FX=J.trainSim[wX.key]
if FX and FX.sig==EX and not FX.pending and os.time()-(FX.at or 0)<6*3600 then
return FX
end
local GX={sig=EX,base=BX,uuid=xX.uuid,at=os.time(),ok=false,margin=DX,pending=true}
J.trainSim[wX.key]=GX
local HX,IX=W.levelFor(wX)
if wX.ldOverride then
HX=wX.ldOverride
end
if not HX then
GX.why,GX.pending=Byc[2349],nil
return GX
end
local JX=W.info(HX,wX.key,IX,wX.mod)
local KX={}
for LX,MX in ipairs(yX)do
local NX=zX.collection:get_unit_by_uuid(MX)
if NX then
table.insert(KX,NX)
end
end
local OX=zX.collection:get_unit_by_uuid(xX.uuid)
if not OX or#KX==0 then
GX.why,GX.pending=Byc[2350],nil
return GX
end
local PX=W.run(JX,W.teamFrom(KX,JX.map),{hpMul=1})
local QX=JX.infinite and W.unbound(HX)
local RX=QX and O.infTier(W.run(JX,W.teamFrom(KX,JX.map),{hpMul=DX}).wave)or nil
local SX={}
for TX,UX in ipairs(KX)do
if not N.isFarm(UX.unit_id)then
local VX,WX=pcall(N.score,UX,wX.mod)
table.insert(SX,{i=TX,sc=VX and WX or 0})
end
end
table.sort(SX,function(XX,YX)
return XX.sc<YX.sc
end)
local ZX
for _X=1,math.min(3,#SX)do
local aY=table.clone(KX)
aY[SX[_X].i]=OX
local bY=W.teamFrom(aY,JX.map)
local cY=W.run(JX,bY,{hpMul=DX,train=xX.uuid})
if(QX and O.infTier(cY.wave)>=RX)or(not QX and cY.won)then
local dY=W.run(JX,bY,{hpMul=1,train=xX.uuid})
local eY=(dY.tk or 0)/math.max(0.5,dY.t/60)
if(dY.won or QX)and(not ZX or eY>math.max(ZX.rate*1.5,ZX.rate+1))then
ZX={out=KX[SX[_X].i].unit_id,r=dY,rate=eY,trial=aY}
end
end
end
GX.ownMin=PX.t/60
if not ZX then
GX.why=QX and string.format(Byc[2351],RX,CX and Byc[2352]or Byc[2353])or CX and Byc[2354]or Byc[2355]
else
GX.out,GX.tk,GX.minutes=ZX.out,ZX.r.tk or 0,ZX.r.t/60
GX.uuids={}
for fY,gY in ipairs(ZX.trial)do
table.insert(GX.uuids,gY.uuid)
end
GX.slow=(PX.won and not QX)and GX.minutes/math.max(0.1,GX.ownMin)or 1
if GX.tk<=0 and next(J.train.real)==nil then
GX.why=Byc[2356]
elseif GX.slow>bb.SLOW then
GX.why=string.format(Byc[2357],math.floor((GX.slow-1)*100+0.5))
else
GX.ok=true
end
end
GX.pending=nil
j.log(1,Byc[2358],string.format(Byc[2359],wX.label,N.name(xX.id),GX.out and(Byc[2360]..N.name(GX.out))or Byc[424],GX.ok and string.format(Byc[2361],math.floor((bb.perRun(wX.key,xX.id)or 0)+0.5),xX.what,GX.minutes,GX.ownMin)or tostring(GX.why)))
j.saveSoon()
return GX
end
function bb.home()
local hY=J.train.on
if not hY then
return
end
J.train.on=nil
j.saveSoon()
if not bb.same(bb.team(),hY.uuids or{})then
j.log(1,Byc[2358],Byc[2362])
if not I.autoTeam then
J.savedTeam=nil
end
return
end
if J.savedTeam and bb.same(J.savedTeam,hY.base)then
P.restoreTeam()
else
P.equipTeam(hY.base,Byc[2363])
end
j.log(1,Byc[2358],N.name(hY.out or Byc[1733])..Byc[2364])
end
function bb.apply(iY)
