if jY and(jY.left or 0)>0 and iY and jY.key==iY.key then
bb.home()
return j.status(Byc[2365],Byc[2366])
end
local kY=I.trainTakedowns and bb.target()or nil
if not kY then
bb.home()
return j.status(Byc[2365],I.trainTakedowns and Byc[2367]or Byc[2368])
end
local lY=N.name(kY.id)
local mY=string.format(Byc[2369],kY.what,M.fmt(kY.have),M.fmt(kY.need))
local nY=J.train.on
local oY=nY and nY.base or bb.team()
for pY,qY in ipairs(oY)do
if qY==kY.uuid then
return j.status(Byc[2365],string.format(Byc[2370],lY,mY))
end
end
local rY,sY=bb.eligible(iY)
local tY
if rY then
j.status(Byc[2365],string.format(Byc[2371],lY,iY.label))
tY=bb.plan(iY,kY,oY)
rY,sY=tY.ok,tY.why
end
if not rY then
bb.home()
return j.status(Byc[2365],string.format(Byc[2372],lY,mY,iY.label,tostring(sY)))
end
