P.equipTeam(tY.uuids,string.format(Byc[2373],lY,N.name(tY.out),iY.label))
local uY=M.now()
while M.now()-uY<4 and not bb.same(bb.team(),tY.uuids)do
task.wait(0.25)
end
if not bb.same(bb.team(),tY.uuids)then
if J.savedTeam and bb.same(J.savedTeam,oY)then
P.restoreTeam()
else
P.equipTeam(oY,Byc[2374])
end
J.train.bad[iY.key]=os.time()+3600
j.log(1,Byc[2358],Byc[2375]..iY.label..Byc[2376])
return j.status(Byc[2365],lY..Byc[2377])
end
J.train.on={uuid=kY.uuid,id=kY.id,to=kY.to,what=kY.what,have=kY.have,need=kY.need,got=0,base=oY,uuids=tY.uuids,out=tY.out,key=iY.key,at=os.time()}
j.log(1,Byc[2358],string.format(Byc[2378],lY,N.name(tY.out),iY.label,mY))
end
J.train.on.key=iY.key
local vY,wY=bb.perRun(iY.key,kY.id)
j.status(Byc[2365],string.format(Byc[2379],lY,N.name(tY.out),iY.label,mY,math.floor((vY or 0)+0.5),wY and Byc[424]or Byc[2380]))
end
