table.insert(fZ,{level=jZ.id,world=hZ})
end
end
JY.artifact={list=fZ,interval=dZ.interval,ends=tonumber(dZ.ends_at),ad=type(eZ)==Byc[1495]and eZ or(JY.artifact and JY.artifact.interval==dZ.interval and JY.artifact.ad)or nil}
end
JY.at=os.time()
