function P.rewards()
if not I.rewards then
return j.status(Byc[2397],Byc[1507])
end
local kZ=H.session()
local lZ=H.prof()
if not(kZ and lZ)then
return
end
local mZ={}
if(os.time()-(tonumber(lZ.last_daily_reward_claimed_time)or 0))>=(H.GS.DAILY_REWARD_WAIT or 82800)then
local nZ,oZ=j.request(Byc[1647],Byc[2398])
if nZ and oZ then
table.insert(mZ,Byc[2399])
end
end
for pZ,qZ in pairs(kZ.quest_handler.quest_profile_data.quests or{})do
local rZ,sZ=pcall(H.QCC.is_quest_complete,kZ,qZ)
if rZ and sZ and not J.claims[pZ]then
local tZ,uZ=j.request(Byc[2400],Byc[2401],pZ)
if tZ and uZ then
J.claims[pZ]=os.time()
table.insert(mZ,Byc[2402]..tostring(qZ.quest_info and(qZ.quest_info.name or qZ.quest_info.id)or Byc[424]))
else
J.claims[pZ]=os.time()-259200+3600
end
task.wait(0.3)
