W.INF_CAP=80
function W.evaluate(ppb,qpb)
local rpb=W.run(ppb,qpb,{hpMul=1})
local spb={won=rpb.won,wave=rpb.wave,minutes=rpb.t/60,aliveAt=rpb.aliveAt,total=ppb.total,at=os.time()}
if ppb.infinite and W.unbound(ppb.ld)then
spb.p=1
spb.margin=rpb.won and string.format(Byc[2726],ppb.total)or string.format(Byc[2727],rpb.wave,rpb.t/60)
elseif rpb.won then
local tpb=W.run(ppb,qpb,{hpMul=1.3})
spb.p=tpb.won and 0.92 or 0.7
spb.margin=tpb.won and Byc[2728]or Byc[2729]
else
local upb=W.run(ppb,qpb,{hpMul=0.75})
spb.p=upb.won and 0.25 or 0.05
spb.margin=upb.won and string.format(Byc[2730],rpb.wave)or string.format(Byc[2731],rpb.wave,ppb.total)
if not upb.won then
local vpb=W.run(ppb,qpb,{hpMul=0.25})
if not vpb.won then
spb.p,spb.hopeless=0.005,true
spb.margin=string.format(Byc[2732],rpb.wave,ppb.total)
end
end
end
return spb
end
function W.trust(wpb,xpb)
local ypb=wpb.cal or{}
if type(ypb.alive)~=Byc[1495]or ypb.teamSig~=W.sig((function()
local zpb={}
for Apb,Bpb in ipairs(xpb)do
table.insert(zpb,Bpb.u)
end
return zpb
end)())then
return nil
end
if wpb.key==Byc[1808]and not ypb.aliveLvl then
return nil
end
if ypb.aliveLvl and wpb.ld and wpb.ld.id and ypb.aliveLvl~=tostring(wpb.ld.id)..(eb.is(wpb.ld.id)and(Byc[2733]..tostring(wpb.ld.map))or Byc[424])then
return nil
end
local Cpb=W.run(wpb,xpb,{hpMul=1})
local Dpb,Epb,Fpb=0,0,0
for Gpb=3,math.min(Cpb.wave,tonumber(ypb.lastWave)or 99)do
local Hpb=tonumber(ypb.alive[tostring(Gpb)])
local Ipb=Cpb.aliveAt[Gpb]
if Hpb and Ipb and Hpb>0 then
Dpb=Dpb+Hpb
Epb=Epb+Ipb
Fpb=Fpb+1
end
end
if Fpb<2 or Epb<=0 then
return nil
end
local Jpb=Dpb/Epb
return{ratio=Jpb,ok=Jpb>=0.75 and Jpb<=1.33,waves=Fpb}
end
W.GROWN_LEVEL,W.GROWN_MIN=50,6
function W.grownKinds()
local Kpb=H.session()
local Lpb,Mpb={},0
for Npb,Opb in pairs(Kpb.profile_data.collection.owned_units)do
local Ppb=Opb.unit_id
if not Lpb[Ppb]and H.Units[Ppb]and not N.isFarm(Ppb)and N.rows(Ppb)and not N.hidden(Ppb)then
local Qpb,Rpb=pcall(H.USC.calculate_level,Ppb,tonumber(Opb.xp)or 0)
if Qpb and(tonumber(Rpb)or 0)>=W.GROWN_LEVEL then
Lpb[Ppb]=true
Mpb=Mpb+1
end
end
end
return Mpb
end
