local Eqb=Dqb and Dqb.atk and N.attackInfo(Dqb.atk,Dqb.range)
if Eqb and(Eqb.slowTime>0 or Eqb.stun>0)then
table.insert(Bqb,hqb[Cqb].u)
end
end
for Fqb=1,math.min(3,#Bqb)do
table.insert(rqb,Bqb[Fqb])
end
for Gqb=11,#hqb do
local Hqb=hqb[Gqb].u.unit_id
if N.allyBuff(Hqb)or N.BLESS.by[Hqb]or N.GALE[Hqb]then
table.insert(rqb,hqb[Gqb].u)
end
end
if Tpb and((Tpb.flyChance or 0)>0 or Tpb.mapFly or(Tpb.shield or 0)>0)then
local Iqb,Jqb={},{}
for Kqb=11,#hqb do
local Lqb=hqb[Kqb].u
local Mqb=N.rows(Lqb.unit_id)[0]
if N.airFrom(Lqb.unit_id)==0 then
table.insert(Iqb,Lqb)
end
local Nqb,Oqb=tonumber(Mqb and Mqb.cd)or 0,tonumber((H.Units[Lqb.unit_id]or{}).cost)or 0
if Nqb>0 and Oqb>0 and N.range(Lqb,0)>=15 then
local Pqb=N.attackInfo(Mqb.atk,Mqb.range)
table.insert(Jqb,{u=Lqb,v=Pqb.n*Pqb.hits/Nqb/Oqb*math.min(6,N.cap(Lqb))})
end
end
table.sort(Jqb,function(Qqb,Rqb)
return Qqb.v>Rqb.v
end)
for Sqb=1,math.min(4,#Iqb)do
table.insert(rqb,Iqb[Sqb])
end
for Tqb=1,math.min(6,#Jqb)do
table.insert(rqb,Jqb[Tqb].u)
end
end
local Uqb,Vqb={},{}
for Wqb,Xqb in ipairs(rqb)do
if not Uqb[Xqb]then
Uqb[Xqb]=true
table.insert(Vqb,Xqb)
end
end
Vqb.rest={}
for Yqb,Zqb in ipairs(hqb)do
if not Uqb[Zqb.u]then
table.insert(Vqb.rest,Zqb.u)
end
end
return Vqb
end
function W.objective(_qb)
return(_qb.won and 1000 or 0)+_qb.wave*10-(_qb.won and _qb.t/60 or((_qb.left or 1)*9-math.min(9,_qb.t/60)))
end
W.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function W.cliff(arb,brb,crb)
local drb
for erb,frb in ipairs(W.LADDER)do
drb=W.run(arb,brb,{hpMul=frb,layout=crb})
if not drb.won then
return frb,drb
end
end
return W.LADDER[#W.LADDER],drb
end
function W.exam(grb,hrb)
local irb,jrb,krb=W.teamFrom(hrb,grb.map),0,0
for lrb,mrb in ipairs(W.LADDER)do
local nrb,orb=0,0
for prb,qrb in ipairs({0.92,1,1.08})do
local rrb=W.run(grb,irb,{hpMul=mrb*qrb})
if rrb.won then
nrb=nrb+1
end
orb=orb+rrb.wave
end
jrb,krb=jrb+nrb,orb/3
task.wait()
if nrb==0 then
break
end
end
return jrb,krb
end
W.ZONE_CLOSE,W.ZONE_GAIN=1.3,20
function W.zoneKey(srb)
return tostring(srb.key)..Byc[1606]..tostring(srb.map)
end
function W.zoneChoice(trb,urb,vrb,wrb)
if I.killZone==false or trb.zone or(trb.infinite and W.unbound(trb.ld))then
return false
end
local xrb=J.zoneRec[W.zoneKey(trb)]
local yrb=xrb and(xrb.style==Byc[2715]or(xrb.style==nil and xrb.zone==true))
if xrb and xrb.won then
return yrb==true,yrb and Byc[2734]or nil
end
if xrb and yrb then
return false,Byc[2735]
end
local zrb=J.modes[trb.key]
local Arb=zrb and tonumber(zrb.streak)or 0
if not xrb and zrb and(tonumber(zrb.wins)or 0)>0 and Arb==0 and trb.key~=Byc[1808]and trb.key~=Byc[1804]then
return false
end
local Brb=xrb~=nil or Arb>0
local Crb=wrb and vrb<=1 or(not wrb and vrb<=W.ZONE_CLOSE)
if not(Brb or Crb)then
return false
end
local Drb=table.clone(trb)
Drb.zone=true
local function Erb(Frb)
local Grb=0
for Hrb,Irb in ipairs({0.92,1,1.08})do
Grb=Grb+W.objective(W.run(Frb,urb,{hpMul=vrb*Irb}))
end
return Grb/3
end
local Jrb=Erb(Drb)-Erb(trb)
if Brb and Jrb> -W.ZONE_GAIN then
return true,Byc[2736],Jrb
end
if Crb and Jrb>W.ZONE_GAIN then
return true,string.format(Byc[2737],vrb),Jrb
end
return false,nil,Jrb
end
function W.strength(Krb,Lrb)
local Mrb,Nrb,Orb,Prb,Qrb=W.teamFrom(Lrb,Krb.map),0,0,0,0
for Rrb,Srb in ipairs(W.LADDER)do
local Trb,Urb=0,0
for Vrb,Wrb in ipairs({0.92,1,1.08})do
local Xrb=W.run(Krb,Mrb,{hpMul=Srb*Wrb})
if Xrb.won then
Trb=Trb+1
end
Urb=Urb+Xrb.wave
end
Nrb,Qrb=Nrb+Trb,Urb/3
if Srb==1 then
Orb,Prb=Trb,Urb/3
end
task.wait()
if Trb==0 then
break
end
end
return Nrb,Orb,Prb,Qrb
end
function W.bestTeam(Yrb,Zrb,_rb,asb)
local bsb=M.now()
asb=asb or 25
local csb=table.clone(Zrb)
local dsb,esb=W.cliff(Yrb,W.teamFrom(csb,Yrb.map))
local function fsb(gsb)
local hsb=0
for isb,jsb in ipairs(gsb)do
if N.isFarm(jsb.unit_id)then
hsb=hsb+1
end
end
return hsb
end
local ksb=fsb(_rb)>0
local function lsb(msb)
local nsb=0
for osb,psb in ipairs(msb)do
if not N.isFarm(psb.unit_id)and not N.allyBuff(psb.unit_id)then
nsb=nsb+N.cap(psb)
end
end
return nsb
end
local qsb
while#csb<6 do
local rsb,ssb
local tsb=ksb and fsb(csb)==0
for usb,vsb in ipairs(_rb)do
local wsb=false
for xsb,ysb in ipairs(csb)do
if ysb.unit_id==vsb.unit_id then
wsb=true
end
end
if not wsb and(not tsb or N.isFarm(vsb.unit_id))then
local zsb=table.clone(csb)
table.insert(zsb,vsb)
local Asb=W.run(Yrb,W.teamFrom(zsb,Yrb.map),{hpMul=dsb})
local Bsb=W.objective(Asb)
if not ssb or Bsb>ssb then
rsb,ssb,qsb=vsb,Bsb,Asb
end
end
end
if not rsb then
break
end
table.insert(csb,rsb)
end
if ksb and fsb(csb)==0 then
local Csb,Dsb
for Esb=1,#csb do
for Fsb,Gsb in ipairs(_rb)do
if N.isFarm(Gsb.unit_id)then
local Hsb=table.clone(csb)
Hsb[Esb]=Gsb
local Isb=W.run(Yrb,W.teamFrom(Hsb,Yrb.map),{hpMul=dsb})
local Jsb=W.objective(Isb)
if not Dsb or Jsb>Dsb then
Csb,Dsb,qsb=Hsb,Jsb,Isb
end
end
end
end
if Csb then
csb=Csb
end
end
local function Ksb(Lsb,Msb)
local Nsb=W.teamFrom(Lsb,Yrb.map)
return(W.objective(Msb)+W.objective(W.run(Yrb,Nsb,{hpMul=dsb*0.92}))+W.objective(W.run(Yrb,Nsb,{hpMul=dsb*1.08})))/3
end
local Osb,Psb=qsb or esb,Ksb(csb,qsb or esb)
if type(_rb.rest)==Byc[1495]and#_rb.rest>0 then
local Qsb,Rsb
for Ssb,Tsb in ipairs(csb)do
if not N.isFarm(Tsb.unit_id)and not N.allyBuff(Tsb.unit_id)then
local Usb,Vsb=pcall(N.score,Tsb,Yrb.mod)
Vsb=(Usb and Vsb or 0)*N.skinMul(Tsb,Yrb.skinSet)
if not Rsb or Vsb<Rsb then
Qsb,Rsb=Ssb,Vsb
end
end
end
if Qsb then
local Wsb,Xsb={},M.now()
for Ysb,Zsb in ipairs(_rb.rest)do
if M.now()-Xsb>5 then
break
end
local _sb=false
for atb,btb in ipairs(csb)do
if btb.unit_id==Zsb.unit_id then
_sb=true
end
end
if not _sb then
local ctb=table.clone(csb)
ctb[Qsb]=Zsb
table.insert(Wsb,{u=Zsb,o=W.objective(W.run(Yrb,W.teamFrom(ctb,Yrb.map),{hpMul=dsb}))})
end
end
table.sort(Wsb,function(dtb,etb)
return dtb.o>etb.o
end)
_rb=table.clone(_rb)
for ftb=1,math.min(4,#Wsb)do
table.insert(_rb,1,Wsb[ftb].u)
end
bsb=bsb+(M.now()-Xsb)
end
end
for gtb=1,2 do
local htb=false
for itb=1,#csb do
for jtb,ktb in ipairs(_rb)do
if M.now()-bsb>asb then
return csb,Osb,dsb,esb
end
local ltb=false
for mtb,ntb in ipairs(csb)do
if ntb.unit_id==ktb.unit_id then
ltb=true
end
end
if not ltb then
local otb=table.clone(csb)
otb[itb]=ktb
if(not ksb or fsb(otb)>0)and lsb(otb)>=math.min(8,lsb(csb))then
local ptb=W.run(Yrb,W.teamFrom(otb,Yrb.map),{hpMul=dsb})
local qtb=W.objective(ptb)
if qtb>Psb+1 then
qtb=Ksb(otb,ptb)
if qtb>Psb+1 then
csb,Psb,Osb,htb=otb,qtb,ptb,true
end
end
end
end
end
end
if not htb then
break
end
end
return csb,Osb,dsb,esb
end
function W.evolutions()
local rtb=H.session()
local stb,ttb={},{}
local utb=rtb.inventory
local function vtb(wtb)
local xtb=0
pcall(function()
xtb=utb:get_number_of_owned_item(wtb)
end)
return xtb
end
for ytb,ztb in pairs(rtb.profile_data.collection.owned_units)do
local Atb=H.Units[ztb.unit_id]
if Atb and Atb.evolve and Atb.evolve.evolve_unit and not Atb.evolve.hide_from_ui and not ttb[ztb.unit_id]and H.Units[Atb.evolve.evolve_unit]then
ttb[ztb.unit_id]=true
local Btb=ztb.shiny and Atb.evolve.shiny or Atb.evolve.normal
if Btb then
local Ctb={}
for Dtb,Etb in pairs(Btb.item_requirement or{})do
if vtb(Etb.item_id)<(Etb.amount or 1)then
table.insert(Ctb,string.format(Byc[2086],(H.Items[Etb.item_id]or{}).name or Etb.item_id,vtb(Etb.item_id),Etb.amount))
end
end
for Ftb,Gtb in pairs(Btb.unit_requirement or{})do
local Htb=0
for Itb,Jtb in pairs(rtb.profile_data.collection.owned_units)do
if Jtb.unit_id==Gtb.unit_id and(not Gtb.shiny or Jtb.shiny)then
Htb=Htb+1
end
end
if Htb<(Gtb.amount or 1)then
table.insert(Ctb,string.format(Byc[2086],N.name(Gtb.unit_id),Htb,Gtb.amount))
end
end
local Ktb=ab.killsShort(rtb.collection:get_unit_by_uuid(ztb.uuid)or ztb,Btb)
if Ktb then
table.insert(Ctb,string.format(Byc[2369],Ktb.what,M.fmt(Ktb.have),M.fmt(Ktb.need)))
end
if#Ctb<=1 then
local Ltb=rtb.collection:get_unit_by_uuid(ztb.uuid)or ztb
table.insert(stb,{u=Ltb,from=ztb.unit_id,to=Atb.evolve.evolve_unit,missing=Ctb,evolved={unit_id=Atb.evolve.evolve_unit,uuid=Byc[2078]..tostring(Ltb.uuid),xp=Ltb.xp,traits=Ltb.traits,trait_stats=Ltb.trait_stats,further_modifiers=Ltb.further_modifiers}})
end
end
end
end
return stb
end
function W.levelFor(Mtb)
local Ntb=J.simCal[Mtb.key]
if Mtb.kind==Byc[1647]and J.live.daily and J.live.daily.ld then
return J.live.daily.ld,J.live.daily.challenge
end
if eb.is(Mtb.level)and J.live.event and J.live.event.ld then
return J.live.event.ld,nil
end
local Otb=Mtb.kind~=Byc[1509]or(Ntb and type(Ntb.ld)==Byc[1495]and Ntb.ld.id==Mtb.level and Ntb.ch==Mtb.challenge)
if Ntb and type(Ntb.ld)==Byc[1495]and Otb then
return Ntb.ld,Ntb.ch
end
if Mtb.kind==Byc[1509]and H.Levels[Mtb.level]then
local Ptb=W.slim(H.Levels[Mtb.level])
Ptb._difficulty=Byc[1688]
Ptb._gamemode=Byc[1509]
Ptb._challenge=Mtb.challenge
return Ptb,Mtb.challenge
end
if H.Levels[Mtb.level]then
local Qtb=W.slim(H.Levels[Mtb.level])
Qtb._difficulty=Mtb.diff
Qtb._gamemode=Qtb._OVERRIDE_GAMEMODE or((Mtb.kind==Byc[1531]or Mtb.kind==Byc[1648])and Byc[1531])or(Qtb.infinite and Byc[1514])or Byc[1530]
return Qtb,nil
end
end
function W.plan(Rtb,Stb,Ttb,Utb)
local Vtb,Wtb=W.levelFor(Rtb)
if Rtb.ldOverride then
Vtb=Rtb.ldOverride
end
if not Vtb then
return nil
end
local Xtb=Rtb.mod or(Rtb.kind==Byc[1647]and J.live.daily and J.live.daily.mod)or O.levelMod(Rtb.level)
local Ytb=W.info(Vtb,Rtb.key,Wtb,Xtb)
local Ztb=Utb
if not Ztb then
Ztb={}
for _tb,aub in ipairs(N.equipped())do
table.insert(Ztb,aub.u)
end
end
local bub=W.teamFrom(Ztb,Ytb.map)
local cub=W.evaluate(Ytb,bub)
local dub,eub=pcall(W.zoneChoice,Ytb,bub,cub.p>=0.92 and 1.7 or cub.p>=0.7 and 1.3 or 1,false)
if dub and eub then
Ytb.zone=true
cub=W.evaluate(Ytb,bub)
cub.zone=true
cub.margin=cub.margin..Byc[2738]
end
cub.sig=W.sig(Ztb)
cub.trust=W.trust(Ytb,bub)
cub.label=Rtb.label
cub.calibrated=(tonumber(Ytb.cal.n)or 0)>0
J.simRes[Rtb.key]=cub
cub.aliveAt=nil
j.log(1,Byc[2739],string.format(Byc[2740],Rtb.label,cub.margin,cub.calibrated and Byc[2741]or Byc[2742],cub.trust and string.format(Byc[2743],cub.trust.ratio)or Byc[2744]))
local fub=O.rec(Rtb.key)
if I.simTeams and Stb and type(fub.winTeam)==Byc[1495]and#fub.winTeam>0 then
local gub=H.session()
local hub={}
for iub,jub in ipairs(fub.winTeam)do
local kub=gub.collection:get_unit_by_uuid(jub)
if kub then
table.insert(hub,kub)
end
end
if#hub== #fub.winTeam then
local lub=W.teamFrom(hub,Ytb.map)
local mub=W.run(Ytb,lub,{hpMul=1})
local nub=W.trust(Ytb,lub)
local oub=nub and not nub.ok
if not mub.won or oub then
local pub,qub={},{}
for rub,tub in ipairs(hub)do
table.insert(pub,N.name(tub.unit_id))
table.insert(qub,tub.unit_id)
end
J.simTeam[Rtb.key]={uuids=fub.winTeam,names=pub,ids=qub,won=true,wave=Ytb.total,better=W.sig(hub)~=cub.sig,cur={won=cub.won,wave=cub.wave},at=os.time(),label=Rtb.label,base=cub.sig,why=Byc[2745]}
j.log(1,Byc[2739],string.format(Byc[2746],Rtb.label,table.concat(pub,Byc[1591]),oub and string.format((nub.ratio or 0)<0.1 and Byc[2747]or Byc[2748],nub.ratio or 0)or string.format(Byc[2749],mub.wave),fub.winTeamN or 1))
return cub
end
end
end
if I.simTeams and Stb then
local uub,vub,wub,xub,yub=pcall(W.bestTeam,Ytb,Ztb,W.pool(Xtb,Ytb),Ttb)
if uub and vub then
local zub=W.sig(vub)~=cub.sig
if zub and cub.won and(cub.p or 0)>=0.92 then
local Aub={}
for Bub,Cub in ipairs(vub)do
table.insert(Aub,N.name(Cub.unit_id))
end
j.log(1,Byc[2739],string.format(Byc[2750],Rtb.label,table.concat(Aub,Byc[1591])))
vub,zub=Ztb,false
end
local Dub=Byc[424]
if zub then
local Eub,Fub=W.exam(Ytb,Ztb)
local Gub,Hub=W.exam(Ytb,vub)
local Iub= #vub> #Ztb and Gub==Eub and Hub>=Fub
if Gub>Eub or(Gub==Eub and Hub>Fub)or Iub then
Dub=string.format(Byc[2751],Gub,Eub)..(Iub and string.format(Byc[2752],#vub,#Ztb)or Byc[424])
else
local Jub={}
for Kub,Lub in ipairs(vub)do
table.insert(Jub,N.name(Lub.unit_id))
end
j.log(1,Byc[2739],string.format(Byc[2753],Rtb.label,table.concat(Jub,Byc[1591]),Gub,Eub))
vub,zub=Ztb,false
end
end
local Mub=W.run(Ytb,W.teamFrom(vub,Ytb.map),{hpMul=1})
if zub then
cub.playing=Mub.won and Byc[2754]or string.format(Byc[2755],Mub.wave,Ytb.total)
end
local Nub,Oub={},{}
for Pub,Qub in ipairs(vub)do
table.insert(Nub,Qub.uuid)
table.insert(Oub,N.name(Qub.unit_id))
end
local Rub={}
for Sub,Tub in ipairs(vub)do
table.insert(Rub,Tub.unit_id)
end
J.simTeam[Rtb.key]={uuids=Nub,names=Oub,ids=Rub,won=Mub.won,wave=Mub.wave,better=zub,cur={won=cub.won,wave=cub.wave},at=os.time(),label=Rtb.label,base=cub.sig}
j.log(1,Byc[2739],string.format(Byc[2756],Rtb.label,Mub.won and Byc[1856]or(Byc[2757]..Mub.wave),table.concat(Oub,Byc[1591]),zub and(string.format(Byc[2758],xub,wub.won and Byc[1856]or Byc[1857],wub.wave,yub.won and Byc[1856]or Byc[1857],yub.wave)..Dub)or Byc[2759]))
local Uub={}
for Vub,Wub in ipairs(W.evolutions())do
local Xub
if N.hidden(Wub.from)or N.hidden(Wub.to)then
Xub=Byc[2088]
else
local Yub=table.clone(vub)
local Zub=false
for _ub,avb in ipairs(Yub)do
if avb.unit_id==Wub.from then
Yub[_ub]=Wub.evolved
Zub=true
end
end
if not Zub then
local bvb,cvb=nil,math.huge
for dvb,evb in ipairs(Yub)do
if not N.isFarm(evb.unit_id)then
local fvb,gvb=pcall(N.score,evb,Xtb)
if fvb and gvb<cvb then
bvb,cvb=dvb,gvb
end
end
end
if bvb then
Yub[bvb]=Wub.evolved
end
end
local hvb=W.run(Ytb,W.teamFrom(Yub,Ytb.map),{hpMul=1})
if hvb.won and not Mub.won then
Xub=Byc[2760]..Rtb.label..Byc[2761]
elseif hvb.wave>Mub.wave then
Xub=string.format(Byc[2762],Rtb.label,hvb.wave,Mub.wave)
elseif hvb.won and Mub.won and hvb.t<Mub.t-6 then
Xub=string.format(Byc[2763],Rtb.label,(Mub.t-hvb.t)/60)
else
Xub=Mub.won and(Byc[2764]..Rtb.label..Byc[2765])or(Byc[2766]..Rtb.label)
end
end
table.insert(Uub,{from=N.name(Wub.from),to=N.name(Wub.to),ready= #Wub.missing==0,missing=Wub.missing[1],gain=Xub,mode=Rtb.label})
end
J.simEvo=Uub
end
end
j.saveSoon()
return cub
end
cb.T={CURSE=0,SHOP=1,MONEY=2,GOLD=3,CHEST=4,BOSS=5,OPEN=6,SHRINE=7}
cb.TAG_NAMES={[0]=Byc[2767],[1]=Byc[2172],[2]=Byc[2768],[3]=Byc[2769],[4]=Byc[2770],[5]=Byc[2771],[6]=Byc[2772],[7]=Byc[2773]}
cb.KNOWN={_started=true,_items=true,selected_next=true,next=true,_resources=true}
cb.ROOMS=20
function cb.core()
if not cb._core then
cb._core=H.core(Byc[2774])
end
return cb._core
end
function cb.data()
local ivb=H.prof()
return ivb and type(ivb.dungeon_data)==Byc[1495]and ivb.dungeon_data or nil
end
function cb.item(jvb)
local kvb=cb.core()
return jvb and kvb and type(kvb.ITEMS)==Byc[1495]and kvb.ITEMS[jvb]or nil
end
function cb.isCurse(lvb)
return tostring(lvb):sub(1,7)==Byc[2775]
end
function cb.tags(mvb)
local nvb={}
for ovb,pvb in pairs(type(mvb)==Byc[1495]and type(mvb._t)==Byc[1495]and mvb._t or{})do
if pvb then
nvb[tonumber(ovb)or-1]=true
end
end
return nvb
end
function cb.list(qvb)
local rvb={}
for svb,tvb in pairs(type(qvb)==Byc[1495]and qvb or{})do
local uvb=tonumber(svb)
if uvb and type(tvb)==Byc[1495]then
table.insert(rvb,{choice=uvb,key=svb,r=tvb,tags=cb.tags(tvb),d=tonumber(tvb._d)or 1})
end
end
table.sort(rvb,function(vvb,wvb)
return vvb.choice<wvb.choice
end)
return rvb
end
function cb.rooms(xvb)
