function cb.sim(exb,fxb,gxb)
if not I.sim or type(exb.r._l)~=Byc[1495]then
return nil
end
local hxb=tostring(exb.r._r or(exb.d..Byc[1606]..exb.choice))..(fxb and(Byc[2345]..tostring(fxb))or Byc[424])..(gxb and Byc[2808]or Byc[424])
local ixb=cb.data()
local jxb=cb.fx(ixb,cb.roomCurse(exb.r),fxb)
local kxb=O.teamSig()..Byc[2809]..cb.fxText(jxb)..(I.killZone~=false and Byc[2810]or Byc[424])
local lxb=J.dg.sim[hxb]
if lxb and lxb.sig==kxb then
return not lxb.none and lxb or nil
end
local mxb={}
for nxb,oxb in ipairs(N.equipped())do
table.insert(mxb,oxb.u)
end
if#mxb==0 then
return nil
end
local pxb=W.applyFx(W.info(W.slim(exb.r._l),Byc[1835],nil,cb.mod(exb.r._l)),jxb)
if gxb then
pxb.zone=false
end
local qxb=W.wave(pxb,1,true)
if#qxb==0 then
lxb={none=true,sig=kxb,at=os.time()}
else
local rxb=W.evaluate(pxb,W.teamFrom(mxb,pxb.map))
lxb={p=rxb.p,wave=rxb.wave,won=rxb.won,total=pxb.total,margin=rxb.margin,sig=kxb,at=os.time()}
end
J.dg.sim[hxb]=lxb
if M.count(J.dg.sim)>60 then
local sxb,txb
for uxb,vxb in pairs(J.dg.sim)do
if not txb or(vxb.at or 0)<txb then
sxb,txb=uxb,vxb.at or 0
end
end
J.dg.sim[sxb]=nil
end
j.saveSoon()
return not lxb.none and lxb or nil
end
function cb.winP(wxb)
