local yxb=J.dg.depth[xxb]or{runs=0,wins=0}
local zxb=M.clamp(0.95-0.015*wxb.d,0.5,0.95)
local Axb=((tonumber(yxb.wins)or 0)+zxb*2)/((tonumber(yxb.runs)or 0)+2)
local Bxb,Cxb=pcall(cb.sim,wxb)
if Bxb and Cxb and Cxb.p then
Axb=(Axb*2+Cxb.p)/3
end
return Axb,Bxb and Cxb or nil
end
