end
function cb.curseOk(Nxb,Oxb,Pxb,Qxb,Rxb)
local Sxb=tostring((cb.item(Nxb)or{}).name or Nxb)
local Txb,Uxb,Vxb=cb.curseBar(Oxb,Pxb)
if Txb>0.2 and cb.blindCurse(Oxb,Nxb)then
return false,string.format(Byc[2814],Sxb,Vxb)
end
local function Wxb(Xxb)
return Xxb==nil or(tonumber(Xxb.p)or 1)>=Txb
end
if Qxb then
local Yxb,Zxb=pcall(cb.sim,Qxb,nil,true)
if Yxb and not Wxb(Zxb)then
return false,string.format(Byc[2815],Sxb,(Uxb:gsub(Byc[2816],Byc[2817])),tostring(Zxb.margin or Byc[1733]))
end
end
if#Rxb==0 then
return true
end
local _xb
for ayb,byb in ipairs(Rxb)do
local cyb,dyb=pcall(cb.sim,byb,Nxb,true)
if not cyb or Wxb(dyb)then
return true
end
if not _xb or(tonumber(dyb.p)or 0)>(tonumber(_xb.p)or 0)then
_xb=dyb
end
end
return false,string.format(Byc[2818],Sxb,Uxb,tostring(_xb and _xb.margin or Byc[1733]))
end
