function cb.payValue()
local hyb,iyb=0,0
for jyb,kyb in ipairs(J.dg.pay or{})do
if type(kyb.items)==Byc[1495]then
local lyb=tonumber(kyb.gems)or 0
for myb,nyb in pairs(kyb.items)do
if(tonumber(nyb)or 0)>0 then
lyb=lyb+O.itemValue(myb,nyb)
end
end
hyb,iyb=hyb+lyb,iyb+1
end
end
if iyb<5 then
return nil
end
