end
function cb.pick(oyb)
local pyb,qyb=cb.curses(oyb),cb.lives(oyb)
local ryb=cb.res(oyb)
local syb=cb.rooms(oyb)
local tyb={}
for uyb,vyb in ipairs(syb)do
table.insert(tyb,tostring(vyb.r._r))
end
local wyb=table.concat(tyb,Byc[2111])..string.format(Byc[2819],qyb,ryb,pyb,O.teamSig())
if cb._pick and cb._pick.sig==wyb then
return cb._pick.x
end
local xyb,yyb
for zyb,Ayb in ipairs(syb)do
local Byb=cb.roomValue(Ayb,ryb)
local Cyb,Dyb
for Eyb,Fyb in ipairs(cb.after(oyb,Ayb.choice))do
local Gyb=cb.roomValue(Fyb,ryb)
if not Cyb or Gyb>Cyb then
Cyb,Dyb=Gyb,Fyb
end
end
local Hyb,Iyb=cb.winP(Ayb)
local Jyb=1-(1-Hyb)^math.max(1,qyb)
local Kyb=qyb>=3 and 1 or(qyb==2 and 2 or 6)
Ayb.p,Ayb.sim,Ayb.value,Ayb.nextValue,Ayb.nextRoom=Hyb,Iyb,Byb,Cyb or 0,Dyb
Ayb.score=Jyb*(Byb+0.6*(Cyb or 0))-(1-Hyb)*Kyb
local Lyb,Myb,Nyb=pcall(cb.curseGate,Ayb,oyb)
if Lyb and not Myb then
Ayb.blocked=Nyb
end
if not Ayb.blocked and(not xyb or Ayb.score>xyb.score)then
xyb=Ayb
end
if not yyb or Ayb.score>yyb.score then
yyb=Ayb
end
end
xyb=xyb or yyb
cb._pick={sig=wyb,x=xyb,rooms=syb}
return xyb
end
