end
local YDb=0
for ZDb=2,#TDb do
local _Db,aEb=TDb[ZDb-1],TDb[ZDb]
local bEb=(aEb-_Db).Magnitude
local cEb=math.max(1,math.floor(bEb/2))
for dEb=0,cEb-1 do
local eEb=_Db:Lerp(aEb,dEb/cEb)
table.insert(Q.samples,{pos=eEb,prog=(YDb+bEb*dEb/cEb)/math.max(1,WDb),lane=RDb.Name})
end
YDb=YDb+bEb
end
