function Q.learn()
local s2b,t2b={},{}
local u2b,v2b=0,0
for w2b,x2b in ipairs(Q.mine)do
local y2b=x2b._stats
local z2b=y2b.id.Value
local A2b=y2b:FindFirstChild(Byc[3031])and y2b.total_damage.Value or 0
if not N.isFarm(z2b)then
s2b[z2b]=(s2b[z2b]or 0)+A2b
t2b[z2b]=(t2b[z2b]or 0)+Q.liveDps(x2b,z2b)/math.max(0.5,N.nudge(z2b))
local B2b=N.passive(z2b).mark
if B2b then
t2b[z2b]=t2b[z2b]+B2b.dot*y2b.damage.Value
end
u2b=u2b+A2b
end
end
for C2b,D2b in pairs(t2b)do
v2b=v2b+D2b
end
if u2b<=0 or v2b<=0 then
return
end
Q.lastEff={}
for E2b,F2b in pairs(s2b)do
local G2b,H2b=F2b/u2b,t2b[E2b]/v2b
if H2b>0.02 then
local I2b=J.learn[E2b]or{eff=1,n=0}
local J2b=math.max(0.02,0.25*math.sqrt(30/(30+I2b.n)))
local K2b=M.clamp(G2b/H2b,0.3,3)
Q.lastEff[E2b]=math.floor(K2b*1000+0.5)/1000
I2b.eff=I2b.eff+(K2b-I2b.eff)*J2b
I2b.n=I2b.n+1
J.learn[E2b]=I2b
end
end
end
